-- Исходные обязательные ограничения envelope и соответствие ID внутри payload; ошибки JSON и преобразований дают нарушения.
WITH p AS (SELECT e.*,try(json_parse(event_json)) AS j,try(json_parse(payload)) AS pj FROM {{target:oil_stg__v_event_parsed}} e) SELECT count(*) AS n FROM p WHERE batch_id IS NULL OR j IS NULL OR pj IS NULL OR substr(json_format(j),1,1)<>'{' OR substr(json_format(pj),1,1)<>'{' OR schema_version IS DISTINCT FROM 1 OR event_id IS NULL OR event_id='' OR event_type IS NULL OR event_type NOT IN ('field','well','production_day','downtime') OR entity_id IS NULL OR NOT regexp_like(entity_id,'^[A-Za-z0-9_-]+$') OR entity_version IS NULL OR entity_version<1 OR op IS NULL OR op NOT IN ('U','D') OR event_time IS NULL OR event_time IS DISTINCT FROM try(from_iso8601_timestamp_nanos(json_extract_scalar(j,'$.event_time'))) OR NOT coalesce(regexp_like(json_extract_scalar(j,'$.event_time'),'[Tt].*([Zz]|[+-][0-9]{2}:[0-9]{2})$'),false) OR json_extract_scalar(pj,CASE event_type WHEN 'production_day' THEN '$.production_id' WHEN 'field' THEN '$.field_id' WHEN 'well' THEN '$.well_id' WHEN 'downtime' THEN '$.downtime_id' END) IS DISTINCT FROM entity_id;
